/* @autogenerated */
import { firstValueFrom, Observable } from 'rxjs';
import { Slide } from '@shared/data/repository/provider/repository-provider.interface';
import { ExportColumn } from './entity-export.model';

/** Elementos por petición al recorrer las páginas. */
export const EXPORT_PAGE_SIZE = 200;
/** Máximo de filas de un Excel exportado: evita colgar el navegador con listados enormes. */
export const EXPORT_LIMIT = 100_000;
/** Elementos seleccionados que se piden por `uids` en cada petición (la URL tiene un límite). */
const UIDS_PER_REQUEST = 50;

export interface CollectOptions {
  pageSize?: number;
  limit?: number;
  /** Se comprueba entre página y página: al abortar se deja de pedir y se rechaza con `AbortError`. */
  signal?: AbortSignal;
  /** Elementos leídos hasta ahora. */
  onProgress?: (read: number) => void;
}

export interface Collected<T> {
  items: T[];
  /** Quedaban elementos por leer al llegar al límite. */
  truncated: boolean;
}

type ListPage<T> = (filter: any) => Observable<Slide<T>>;

/** Recorre todas las páginas del filtro hasta acabar o llegar al límite. */
export async function collectAll<T>(
  list: ListPage<T>,
  filter: any,
  options: CollectOptions = {},
): Promise<Collected<T>> {
  const pageSize = options.pageSize ?? EXPORT_PAGE_SIZE;
  const limit = options.limit ?? EXPORT_LIMIT;
  const items: T[] = [];
  let query = { ...filter, limit: pageSize };
  for (;;) {
    options.signal?.throwIfAborted();
    const page = await firstValueFrom(list(query));
    options.signal?.throwIfAborted();
    items.push(...page.content);
    if (items.length >= limit) {
      return { items: items.slice(0, limit), truncated: items.length > limit || page.hasNext };
    }
    options.onProgress?.(items.length);
    if (!page.hasNext || !page.content.length) {
      return { items, truncated: false };
    }
    query = { ...filter, limit: pageSize, ...page.next };
  }
}

/**
 * Vuelve a pedir los elementos seleccionados por su `uid`, por bloques, para exportar su estado actual y
 * completo (las filas del listado pueden ser proyecciones). Conserva el orden de la selección.
 */
export async function collectSelected<T extends { uid: string }>(
  list: ListPage<T>,
  uids: string[],
  options: CollectOptions = {},
): Promise<Collected<T>> {
  const found = new Map<string, T>();
  for (let start = 0; start < uids.length; start += UIDS_PER_REQUEST) {
    const chunk = uids.slice(start, start + UIDS_PER_REQUEST);
    const { items } = await collectAll(list, { uids: chunk }, { ...options, onProgress: undefined });
    items.forEach((item) => found.set(item.uid, item));
    options.onProgress?.(Math.min(uids.length, start + chunk.length));
  }
  const items = uids.flatMap((uid) => (found.has(uid) ? [found.get(uid)!] : []));
  return { items, truncated: false };
}

/** `$ref` de cada referencia de `field` en los elementos, sin repetir. */
export function referencesOf(items: any[], field: string): string[] {
  return [...new Set(items.map((item) => item?.[field]?.$ref).filter((ref): ref is string => !!ref))];
}

/** Formato de Excel de las columnas de fecha; las demás, el general. */
export function formatOf(column: ExportColumn): string | undefined {
  return column.type === 'date' ? 'dd/mm/yyyy' : column.type === 'datetime' ? 'dd/mm/yyyy hh:mm' : undefined;
}

/**
 * Valor de la celda tal como lo lee la importación: booleanos y números nativos, fechas como `Date`, los `enum`
 * con su etiqueta y las referencias con su nombre (o su `$ref` si no se conoce).
 */
export function cellOf(item: any, column: ExportColumn, names: Record<string, string> = {}): unknown {
  const value = item?.[column.field];
  if (value === null || value === undefined || value === '') {
    return null;
  }
  switch (column.type) {
    case 'boolean':
    case 'number':
      return value;
    case 'date':
    case 'datetime': {
      const date = value instanceof Date ? value : new Date(value);
      return isNaN(date.getTime()) ? String(value) : date;
    }
    case 'enum':
      return column.optionTexts?.[value] ?? String(value);
    case 'reference': {
      const ref = typeof value === 'object' ? value.$ref : String(value);
      return ref ? (names[ref] ?? ref) : null;
    }
    default:
      return typeof value === 'object' ? JSON.stringify(value) : String(value);
  }
}
